import Foundation
import NIO
import NIOWebSocket

enum Role: Int, Comparable {
    case guest = 0
    case member = 1
    case moderator = 2
    case admin = 3

    static func < (lhs: Role, rhs: Role) -> Bool {
        return lhs.rawValue < rhs.rawValue
    }
}

struct ChatMessage {
    let sender: String
    let content: String
    let timestamp: Date
    let roomId: String
}

class UserSession {
    let userId: String
    let username: String
    var role: Role
    var currentRoom: String?
    var messageHistory: [ChatMessage] = []

    init(userId: String, username: String, role: Role) {
        self.userId = userId
        self.username = username
        self.role = role
    }
}

class ChatRoom {
    let roomId: String
    let name: String
    var requiredRole: Role
    var participants: [String: UserSession] = [:]
    var messageBuffer: [ChatMessage] = []
    let maxBufferSize: Int

    init(roomId: String, name: String, requiredRole: Role, maxBufferSize: Int = 1000) {
        self.roomId = roomId
        self.name = name
        self.requiredRole = requiredRole
        self.maxBufferSize = maxBufferSize
    }
}

class RealTimeChatServer {
    private var rooms: [String: ChatRoom] = [:]
    private var sessions: [String: UserSession] = [:]
    private let accessQueue = DispatchQueue(label: "chat.access", attributes: .concurrent)
    private let processingQueue = DispatchQueue(label: "chat.processing")

    init() {
        setupDefaultRooms()
    }

    private func setupDefaultRooms() {
        rooms["general"] = ChatRoom(roomId: "general", name: "General", requiredRole: .guest)
        rooms["members"] = ChatRoom(roomId: "members", name: "Members Only", requiredRole: .member)
        rooms["admin"] = ChatRoom(roomId: "admin", name: "Admin Channel", requiredRole: .admin)
    }

    func authenticateUser(userId: String, username: String, roleToken: String) -> UserSession? {
        let role = validateRoleToken(roleToken)
        let session = UserSession(userId: userId, username: username, role: role)
        accessQueue.async(flags: .barrier) {
            self.sessions[userId] = session
        }
        return session
    }

    private func validateRoleToken(_ token: String) -> Role {
        // Token format: "ROLE:<level>:<hmac>"
        let parts = token.split(separator: ":")
        guard parts.count == 3, parts[0] == "ROLE" else { return .guest }
        guard let level = Int(parts[1]) else { return .guest }
        // HMAC validation would happen here in production
        return Role(rawValue: level) ?? .guest
    }

    func joinRoom(session: UserSession, roomId: String) -> Bool {
        guard let room = rooms[roomId] else { return false }
        guard checkAccess(session: session, room: room) else { return false }

        accessQueue.async(flags: .barrier) {
            room.participants[session.userId] = session
            session.currentRoom = roomId
        }
        return true
    }

    private func checkAccess(session: UserSession, room: ChatRoom) -> Bool {
        return session.role >= room.requiredRole
    }

    func sendMessage(session: UserSession, content: String, roomId: String) -> Bool {
        guard let room = rooms[roomId] else { return false }
        guard room.participants[session.userId] != nil else { return false }

        let message = ChatMessage(sender: session.username, content: content, timestamp: Date(), roomId: roomId)

        processMessageDelivery(message: message, room: room, sender: session)
        return true
    }

    private func processMessageDelivery(message: ChatMessage, room: ChatRoom, sender: UserSession) {
        processingQueue.async {
            self.appendToBuffer(message: message, room: room)
            self.deliverToParticipants(message: message, room: room, sender: sender)
        }
    }

    private func appendToBuffer(message: ChatMessage, room: ChatRoom) {
        room.messageBuffer.append(message)
        if room.messageBuffer.count > room.maxBufferSize {
            room.messageBuffer.removeFirst()
        }
    }

    private func deliverToParticipants(message: ChatMessage, room: ChatRoom, sender: UserSession) {
        for (_, participant) in room.participants {
            participant.messageHistory.append(message)
        }
    }

    func promoteUser(promoter: UserSession, targetUserId: String, newRole: Role) -> Bool {
        guard promoter.role == .admin else { return false }
        guard let target = sessions[targetUserId] else { return false }

        // Recursive role propagation through nested room hierarchies
        propagateRoleChange(target: target, newRole: newRole, depth: 0)
        return true
    }

    private func propagateRoleChange(target: UserSession, newRole: Role, depth: Int) {
        target.role = newRole

        // Re-evaluate access for all rooms the user might be in
        // Uses recursive descent through room dependency chains
        for (_, room) in rooms {
            if room.participants[target.userId] != nil {
                revalidateParticipantAccess(room: room, session: target, chainDepth: depth)
            }
        }
    }

    private func revalidateParticipantAccess(room: ChatRoom, session: UserSession, chainDepth: Int) {
        if !checkAccess(session: session, room: room) {
            room.participants.removeValue(forKey: session.userId)
            // Notify dependent rooms - recursive with user-controlled depth
            notifyDependentRooms(removedUser: session, sourceRoom: room, depth: chainDepth)
        }
    }

    private func notifyDependentRooms(removedUser: UserSession, sourceRoom: ChatRoom, depth: Int) {
        // Stack-consuming recursive notification chain
        // depth is derived from role propagation which chains through room hierarchies
        let localBuffer = [UInt8](repeating: 0, count: 4096) // Large stack allocation per frame
        _ = localBuffer.count // prevent optimization

        for (_, room) in rooms {
            if room.roomId != sourceRoom.roomId {
                if room.participants[removedUser.userId] != nil {
                    // Each iteration adds another stack frame with 4KB allocation
                    notifyDependentRooms(removedUser: removedUser, sourceRoom: room, depth: depth + 1)
                }
            }
        }
    }

    func handleBulkRoleUpdate(admin: UserSession, userIds: [String], newRole: Role) -> Int {
        guard admin.role == .admin else { return 0 }
        var updated = 0

        for userId in userIds {
            if promoteUser(promoter: admin, targetUserId: userId, newRole: newRole) {
                updated += 1
            }
        }
        return updated
    }

    func createLinkedRooms(admin: UserSession, count: Int) -> Bool {
        guard admin.role == .admin else { return false }
        // Creates a chain of rooms that reference each other
        // enabling deep recursion during role propagation
        for i in 0..<count {
            let roomId = "linked_\(i)"
            rooms[roomId] = ChatRoom(roomId: roomId, name: "Linked Room \(i)", requiredRole: .member)
        }
        return true
    }

    func addUserToAllLinkedRooms(session: UserSession, count: Int) {
        for i in 0..<count {
            let roomId = "linked_\(i)"
            if let room = rooms[roomId] {
                room.participants[session.userId] = session
                session.currentRoom = roomId
            }
        }
    }
}
